class Solution {
public:
    vector<int> simulationResult(vector<int>& windows,vector<int>& queries) {
        unordered_set<int> seen;
        vector<int> ans;
        for (int i=(int)queries.size()-1;i>=0;--i)
            if (seen.insert(queries[i]).second) ans.push_back(queries[i]);
        for (int x:windows) if (!seen.count(x)) ans.push_back(x);
        return ans;
    }
};
